  "extensionText.theExtensionSignInChanged": "확장 프로그램 로그인이 바뀌었어요.",
  "extensionText.theExtensionStorageOrTheBrowser": "확장 프로그램 저장소나 브라우저 쿠키 파일이 다른 프로세스에서 열려 있어요. Relay가 변경하지 않았어요.",
  "extensionText.theExtensionWasOnThisAccount": "확장 프로그램이 이 계정에 있었지만 로그인이 만료됐어요. 확장 프로그램은 브라우저의 claude.ai 로그인으로 다시 로그인해요. 그래도 Claude의 브라우저 도구가 작동하지 않으면 확장 프로그램 사이드 패널에서 로그인하세요.",
  "extensionText.thisAccountHasNoSavedExtension": "이 계정에는 저장된 확장 프로그램 로그인이 없어요. 이 계정으로 확장 프로그램에 한 번 로그인하세요. 다음 전환 때 Relay가 저장해요.",
  "extensionText.thisAccountSSavedClaudeAi": "이 계정에 저장된 claude.ai 로그인이 오랫동안 사용되지 않아 종료되어서 Relay가 확장 프로그램을 변경하지 않았어요. 브라우저에서 이 계정으로 claude.ai와 확장 프로그램에 한 번 로그인하세요. Relay가 새 로그인을 저장해요.",
  "extensionText.thisToolCannotChangeTheClaude": "이 도구로는 Claude 확장 프로그램 로그인을 변경할 수 없어요. Relay.app에서 설정 → 전환 → Claude 브라우저 확장 프로그램 → 지금 동기화를 사용하세요.",
  "extensionUi.atEachSwitchRelayPutsIn": "전환할 때마다 Relay가 새 계정의 확장 프로그램 로그인과 claude.ai 로그인을 넣어요. 열려 있는 브라우저는 잠시 닫혔다가 탭과 함께 다시 열려요. Relay는 이 브라우저 프로필의 claude.ai 로그인도 바꾸기 때문에 claude.ai 탭이 새 계정으로 열려요. 평소 쓰는 claude.ai 계정을 유지하려면 별도 브라우저 프로필에서 확장 프로그램을 사용하세요.",
  "extensionUi.atEachSwitchRelayPutsInLinux": "전환할 때마다 Relay가 새 계정의 확장 프로그램 로그인과 claude.ai 로그인을 넣어요. 열려 있는 브라우저는 잠시 닫혔다가 탭과 함께 다시 열려요. Linux에서는 로그아웃할 때처럼 브라우저가 닫혀요. “이 페이지 나가기”나 다운로드 확인 창이 표시되지 않고 브라우저가 그대로 닫힐 수 있어요. Relay는 이 브라우저 프로필의 claude.ai 로그인도 바꾸기 때문에 claude.ai 탭이 새 계정으로 열려요. 평소 쓰는 claude.ai 계정을 유지하려면 별도 브라우저 프로필에서 확장 프로그램을 사용하세요.",
  "extensionUi.clickTheClaudeIconInThe": "{browser} 도구 막대에서 Claude 아이콘을 클릭한 다음 “Log in”을 클릭하세요.",
