  "extensionUi.macosDoesNotLetRelayRead": "macOS가 Relay의 {names} 데이터 읽기를 허용하지 않아요. 시스템 설정 › 개인정보 보호 및 보안 › 전체 디스크 접근 권한에서 Relay를 켠 다음 Relay를 다시 시작하세요.",
  "extensionUi.makeSureTheExtensionIsSigned": "확장 프로그램이 {email}(으)로 로그인되어 있는지 확인하세요.",
  "extensionUi.makeSureTheExtensionIsSigned2": "확장 프로그램이 이 계정으로 로그인되어 있는지 확인하세요.",
  "extensionUi.noClaudeExtensionFoundOnThis": "이 컴퓨터에서 Claude 확장 프로그램을 찾지 못했어요.",
  "extensionUi.noClaudeExtensionFoundOnThis2": "이 Mac에서 Claude 확장 프로그램을 찾지 못했어요.",
